     "tema": "Incapacidade absoluta",
     "assertiva": "São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de dezesseis anos e os que, por enfermidade ou deficiência mental, não tiverem o necessário discernimento.",
