     "ponto": "DBA26-CIV-1",
     "tema": "Incapacidade relativa",
     "assertiva": "São relativamente incapazes os maiores de dezesseis e menores de dezoito anos, os ébrios habituais e os viciados em tóxico, aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade, e os pródigos.",
