      "resumo": "Art. 53: o prazo improrrogável é de **60 (sessenta) dias**.",
      "lei": [
       {
        "lei": "L11101",
        "art": "53",
        "par": "",
        "inc": "",
        "rotulo": "Lei 11.101/2005, art. 53",
        "texto": "O plano de recuperação será apresentado pelo devedor em juízo no prazo improrrogável de 60 (sessenta) dias da publicação da decisão que deferir o processamento da recuperação judicial, sob pena de convolação em falência"
       }
      ],
