     "ponto": "DBA26-CIV-5",
     "tema": "Dissolução irregular",
     "assertiva": "Presume-se dissolvida irregularmente a empresa que deixar de funcionar no seu domicílio fiscal sem comunicação aos órgãos competentes, o que legitima o redirecionamento da execução fiscal para o sócio-gerente.",
     "gabarito": "C",
     "comentario": {
      "resumo": "**Súmula 435/STJ** — atenção: é regra da **execução fiscal**. Nas relações civis e empresariais o encerramento irregular, sozinho, não autoriza a desconsideração (Tema 1.210).",
      "juris": [
       {
        "tribunal": "STJ",
        "fonte": "Súmula 435/STJ",
        "data": "14/04/2010",
        "texto": "Presume-se dissolvida irregularmente a empresa que deixar de funcionar no seu domicílio fiscal, sem comunicação aos órgãos competentes, legitimando o redirecionamento da execução fiscal para o sócio-gerente."
       },
       {
        "tribunal": "STJ",
        "fonte": "Tema 1.210/STJ — REsp 1.873.811/SP",
        "data": "07/05/2026",
        "texto": "Nas relações de direito civil e empresarial, a desconsideração da personalidade jurídica exige prova efetiva de abuso (desvio de finalidade ou confusão patrimonial), nos termos do art. 50 do CC (teoria maior); é insuficiente a mera inexistência de bens penhoráveis ou o encerramento irregular das atividades."
       }
      ],
      "palavras_chave": [
       "dissolução irregular",
       "sócio-gerente"
      ]
     }
