      "lei": [
       {
        "lei": "L10741",
        "art": "35",
        "par": "",
        "inc": "",
        "rotulo": "Lei 10.741/2003, art. 35, § 2º",
        "texto": "O Conselho Municipal da Pessoa Idosa ou o Conselho Municipal da Assistência Social estabelecerá a forma de participação prevista no § 1º deste artigo, que não poderá exceder a 70% (setenta por cento) de qualquer benefício previdenciário ou de assistência social percebido pela pessoa idosa."
       }
      ],
