     "tema": "Medidas de proteção",
     "assertiva": "As medidas de proteção à pessoa idosa são aplicáveis sempre que os direitos reconhecidos no Estatuto forem ameaçados ou violados por ação ou omissão da sociedade ou do Estado, por falta, omissão ou abuso da família, curador ou entidade de atendimento, ou em razão de sua condição pessoal.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Art. 43: três hipóteses — **sociedade/Estado**, **família/curador/entidade** e **condição pessoal**.",
      "lei": [
       {
        "lei": "L10741",
        "art": "43",
        "par": "",
        "inc": "",
        "rotulo": "Lei 10.741/2003, art. 43",
        "texto": "As medidas de proteção à pessoa idosa são aplicáveis sempre que os direitos reconhecidos nesta Lei forem ameaçados ou violados: (Redação dada pela Lei nº 14.423, de 2022)\nI – por ação ou omissão da sociedade ou do Estado;\nII – por falta, omissão ou abuso da família, curador ou entidade de atendimento;\nIII – em razão de sua condição pessoal."
       }
      ],
      "palavras_chave": [
       "medidas de proteção",
       "condição pessoal"
      ]
     }
