      "juris": [
       {
        "tribunal": "STJ",
        "fonte": "Tema 1.173/STJ — REsp 2.008.545/DF",
        "data": "08/10/2025",
        "texto": "O corretor de imóveis normalmente não responde por danos ao consumidor decorrentes do descumprimento, pela construtora ou incorporadora, de obrigações do empreendimento, salvo envolvimento nas atividades de incorporação e construção, integração ao mesmo grupo econômico ou confusão ou desvio patrimonial."
       }
      ],
